import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams, useNavigate } from "react-router-dom";
import private_api from "../../server/private_api";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";
import Form from "react-bootstrap/Form";
import Badge from "react-bootstrap/Badge";

const ListaCurso = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [aluno, setAluno] = useState(null);
  const [cursosAluno, setCursosAluno] = useState([]);
  const [professores, setProfessores] = useState({});
  const [loading, setLoading] = useState(true);
  const [inscricoes, setInscricoes] = useState([]);

  // Estados para os modais
  const [showInscricaoModal, setShowInscricaoModal] = useState(false);
  const [showDetalhesModal, setShowDetalhesModal] = useState(false);
  const [cursoDetalhes, setCursoDetalhes] = useState(null);
  const [cursosDisponiveis, setCursosDisponiveis] = useState([]);
  const [cursoSelecionado, setCursoSelecionado] = useState(null);
  const [nivel, setNivel] = useState("");
  const [periodo, setPeriodo] = useState("manha");
  const [enviando, setEnviando] = useState(false);
  const [mensagem, setMensagem] = useState({ texto: "", tipo: "" });

  // Busca cursos disponíveis
  const fetchCursosDisponiveis = async () => {
    try {
      const resposta = await private_api.get("/cursos");
      if (resposta.status === 200) {
        setCursosDisponiveis(resposta.data);
      }
    } catch (error) {
      console.error("Erro ao buscar cursos disponíveis:", error);
      setMensagem({
        texto: "Erro ao carregar cursos disponíveis",
        tipo: "danger",
      });
    }
  };

  // Busca as inscrições do aluno
  const fetchInscricoes = async () => {
    try {
      const resposta = await private_api.get(`/inscricoes/aluno/${id}`);
      if (resposta.status === 200) {
        setInscricoes(resposta.data);
      }
    } catch (error) {
      console.error("Erro ao buscar inscrições:", error);
    }
  };

  // Busca os cursos do aluno e informações dos professores
  const fetchCursosAluno = async () => {
    try {
      const resposta = await private_api.get(`/alunos/${id}/listacursos`);
      if (resposta.status === 200) {
        setCursosAluno(resposta.data);

        const professoresMap = {};
        for (const curso of resposta.data) {
          if (curso.professorId && !professoresMap[curso.professorId]) {
            try {
              const profResposta = await private_api.get(
                `/professores/${curso.professorId}`
              );
              if (profResposta.status === 200) {
                professoresMap[curso.professorId] =
                  profResposta.data.utilizador;
              }
            } catch (error) {
              console.error(
                `Erro ao buscar professor ${curso.professorId}:`,
                error
              );
            }
          }
        }
        setProfessores(professoresMap);
      }
    } catch (error) {
      console.error("Erro ao buscar cursos do aluno:", error);
      setMensagem({
        texto: "Erro ao carregar cursos do aluno",
        tipo: "danger",
      });
    }
  };

  // Busca informações do aluno
  const fetchAluno = async () => {
    try {
      const resposta = await private_api.get(`/alunos/${id}`);
      if (resposta.status === 200) {
        setAluno(resposta.data);
      }
    } catch (error) {
      console.error("Erro ao buscar aluno:", error);
      setMensagem({
        texto: "Erro ao carregar dados do aluno",
        tipo: "danger",
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAluno();
    fetchCursosAluno();
    fetchInscricoes();
  }, [id]);

  // Abre o modal de detalhes
  const handleAbrirDetalhesModal = (curso) => {
    setCursoDetalhes(curso);
    setShowDetalhesModal(true);
  };

  // Fecha o modal de detalhes
  const handleFecharDetalhesModal = () => {
    setShowDetalhesModal(false);
    setCursoDetalhes(null);
  };

  // Atualiza o status da inscrição no banco de dados
  const atualizarStatusInscricao = async (cursoId, novoStatus) => {
    try {
      // Encontra a inscrição correspondente
      const inscricao = inscricoes.find((insc) => insc.cursoId === cursoId);

      if (!inscricao) {
        throw new Error("Inscrição não encontrada");
      }

      // Atualiza o status no backend
      const resposta = await private_api.put(`/inscricoes/${inscricao.id}`, {
        status: novoStatus,
      });

      if (resposta.status === 200) {
        // Atualiza a lista de inscrições localmente
        const updatedInscricoes = inscricoes.map((insc) =>
          insc.id === inscricao.id ? { ...insc, status: novoStatus } : insc
        );
        setInscricoes(updatedInscricoes);

        // Se foi aprovado, atualiza a lista de cursos do aluno
        if (novoStatus === "aprovado") {
          await fetchCursosAluno();
        }

        setMensagem({
          texto: `Status atualizado para ${
            novoStatus === "aprovado" ? "Aprovado" : "Pendente"
          }`,
          tipo: "success",
        });
      }
    } catch (error) {
      console.error("Erro ao atualizar status:", error);
      setMensagem({
        texto: "Erro ao atualizar status. Tente novamente.",
        tipo: "danger",
      });
    }
  };

  // Verifica o status da inscrição
  const getStatusInscricao = (cursoId) => {
    const inscricao = inscricoes.find((insc) => insc.cursoId === cursoId);
    if (!inscricao) return { status: "Não inscrito", badge: "secondary" };

    // Verifica se o aluno está matriculado no curso (curso aparece na lista de cursosAluno)
    const cursoMatriculado = cursosAluno.some((curso) => curso.id === cursoId);

    return cursoMatriculado
      ? { status: "Aprovado", badge: "success" }
      : { status: "Pendente", badge: "warning" };
  };

  // Atualiza o curso selecionado
  const handleSelecionarCurso = (cursoId) => {
    const curso = cursosDisponiveis.find((c) => c.id === cursoId);
    setCursoSelecionado(curso);
    setNivel(curso?.nivel || "");
    setPeriodo(curso?.periodo || "manha");
  };

  // Envia a inscrição
  const handleEnviarInscricao = async () => {
    if (!cursoSelecionado || !nivel || !periodo) {
      setMensagem({ texto: "Preencha todos os campos", tipo: "danger" });
      return;
    }

    setEnviando(true);
    try {
      // Normaliza o período para minúsculas e sem acento
      const periodoNormalizado = periodo.toLowerCase().replace("ã", "a");

      const resposta = await private_api.post("/inscricoes", {
        alunoId: id,
        cursoId: cursoSelecionado.id,
        nivel,
        periodo: periodoNormalizado,
        status: "pendente",
      });

      if (resposta.status === 201) {
        setMensagem({
          texto: "Inscrição enviada com sucesso! Aguarde aprovação.",
          tipo: "success",
        });

        // Envia email para o administrador
        await private_api.post("/email", {
          to: process.env.EMAIL_USER || "admin@example.com",
          subject: `Nova inscrição de ${aluno.utilizador.nome}`,
          text: `O aluno ${aluno.utilizador.nome} solicitou inscrição no curso ${cursoSelecionado.nome}.`,
        });

        // Atualiza as listas
        await fetchInscricoes();
        setShowInscricaoModal(false);
      }
    } catch (error) {
      console.error("Erro ao enviar inscrição:", error);
      setMensagem({
        texto: "Erro ao enviar inscrição. Tente novamente.",
        tipo: "danger",
      });
    } finally {
      setEnviando(false);
    }
  };

  if (loading) {
    return (
      <div
        className="d-flex justify-content-center align-items-center"
        style={{ height: "100vh" }}
      >
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  if (!aluno) {
    return (
      <div
        className="d-flex justify-content-center align-items-center"
        style={{ height: "100vh" }}
      >
        <div className="alert alert-danger">Aluno não encontrado</div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid py-4"
      style={{ backgroundColor: "#E7EFF4", minHeight: "100vh" }}
    >
      {/* Modals */}
      <Modal show={showDetalhesModal} onHide={handleFecharDetalhesModal}>
        <Modal.Header closeButton>
          <Modal.Title>Detalhes do Curso</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {cursoDetalhes && (
            <div>
              <h5>{cursoDetalhes.nome}</h5>
              <p>
                <strong>Nível:</strong> {cursoDetalhes.nivel}
              </p>
              <p>
                <strong>Período:</strong>{" "}
                {cursoDetalhes.periodo === "manha" ? "Manhã" : "Tarde"}
              </p>

              <div className="mt-4">
                <h6>Status da Inscrição:</h6>
                <Badge
                  pill
                  bg={getStatusInscricao(cursoDetalhes.id).badge}
                  className="mb-2"
                >
                  {getStatusInscricao(cursoDetalhes.id).status}
                </Badge>

                {getStatusInscricao(cursoDetalhes.id).status === "Aprovado" ? (
                  <div className="alert alert-success mt-2">
                    Você está matriculado neste curso.
                  </div>
                ) : (
                  <div className="alert alert-warning mt-2">
                    Aguardando aprovação da inscrição.
                  </div>
                )}
              </div>
            </div>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleFecharDetalhesModal}>
            Fechar
          </Button>
          {getStatusInscricao(cursoDetalhes?.id).status === "Pendente" && (
            <Button
              variant="primary"
              onClick={() =>
                atualizarStatusInscricao(cursoDetalhes.id, "aprovado")
              }
            >
              Aprovar Inscrição
            </Button>
          )}
        </Modal.Footer>
      </Modal>

      <Modal
        show={showInscricaoModal}
        onHide={() => setShowInscricaoModal(false)}
        size="lg"
      >
        <Modal.Header closeButton>
          <Modal.Title>Nova Inscrição</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {mensagem.texto && (
            <div className={`alert alert-${mensagem.tipo} mb-3`}>
              {mensagem.texto}
            </div>
          )}

          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Curso</Form.Label>
              <Form.Select
                onChange={(e) =>
                  handleSelecionarCurso(parseInt(e.target.value))
                }
                value={cursoSelecionado?.id || ""}
              >
                <option value="">Selecione um curso</option>
                {cursosDisponiveis.map((curso) => (
                  <option key={curso.id} value={curso.id}>
                    {curso.nome} - {curso.nivel}
                  </option>
                ))}
              </Form.Select>
            </Form.Group>

            {cursoSelecionado && (
              <>
                <Form.Group className="mb-3">
                  <Form.Label>Nível</Form.Label>
                  <Form.Control type="text" value={nivel} readOnly />
                </Form.Group>

                <Form.Group className="mb-3">
                  <Form.Label>Período</Form.Label>
                  <Form.Select
                    value={periodo}
                    onChange={(e) => setPeriodo(e.target.value)}
                  >
                    <option value="manha">Manhã</option>
                    <option value="tarde">Tarde</option>
                  </Form.Select>
                </Form.Group>
              </>
            )}
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button
            variant="secondary"
            onClick={() => setShowInscricaoModal(false)}
          >
            Cancelar
          </Button>
          <Button
            variant="primary"
            onClick={handleEnviarInscricao}
            disabled={enviando || !cursoSelecionado}
          >
            {enviando ? "Enviando..." : "Confirmar Inscrição"}
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Conteúdo Principal */}
      <div className="row justify-content-center">
        <div className="col-md-10">
          {/* Mensagens */}
          {mensagem.texto && !showInscricaoModal && !showDetalhesModal && (
            <div className={`alert alert-${mensagem.tipo} mb-4`}>
              {mensagem.texto}
            </div>
          )}

          {/* Navegação */}
          <div className="card mb-4">
            <div className="card-body p-2">
              <ul className="nav nav-tabs">
                <li className="nav-item">
                  <button className="nav-link active">Cursos</button>
                </li>
                <li className="nav-item">
                  <button
                    className="nav-link"
                    onClick={() => navigate(`/aula/${id}`)}
                  >
                    Aulas
                  </button>
                </li>
                <li className="nav-item">
                  <button
                    className="nav-link"
                    onClick={() => navigate(`/avaliacao/${id}`)}
                  >
                    Avaliações
                  </button>
                </li>
              </ul>
            </div>
          </div>

          {/* Cabeçalho */}
          <div className="d-flex justify-content-between align-items-center mb-4">
            <h2 className="mb-0">Cursos de {aluno.utilizador.nome}</h2>
            <div>
              <button
                className="btn btn-primary me-2"
                onClick={() => {
                  setShowInscricaoModal(true);
                  fetchCursosDisponiveis();
                }}
              >
                Nova Inscrição
              </button>
              <button
                className="btn btn-outline-secondary"
                onClick={() => navigate(`/alunodetalhes/${id}`)}
              >
                Ver Perfil
              </button>
            </div>
          </div>

          {/* Tabela de Cursos */}
          <div className="card mb-4">
            <div className="card-body p-0">
              <div className="table-responsive">
                <table className="table table-hover mb-0">
                  <thead className="table-light">
                    <tr>
                      <th>Curso</th>
                      <th>Nível</th>
                      <th>Início</th>
                      <th>Término</th>
                      <th>Período</th>
                      <th>Professor</th>
                      <th>Status</th>
                      <th>Ações</th>
                    </tr>
                  </thead>
                  <tbody>
                    {cursosAluno.length > 0 ? (
                      cursosAluno.map((curso) => {
                        const status = getStatusInscricao(curso.id);
                        return (
                          <tr key={curso.id}>
                            <td>{curso.nome}</td>
                            <td>{curso.nivel}</td>
                            <td>
                              {new Date(curso.dataInicio).toLocaleDateString()}
                            </td>
                            <td>
                              {new Date(curso.dataFim).toLocaleDateString()}
                            </td>
                            <td>
                              {curso.periodo === "manha" ? "Manhã" : "Tarde"}
                            </td>
                            <td>
                              {professores[curso.professorId]?.nome || "N/A"}
                            </td>
                            <td>
                              <Badge pill bg={status.badge}>
                                {status.status}
                              </Badge>
                            </td>
                            <td>
                              <button
                                className="btn btn-sm btn-outline-primary"
                                onClick={() => handleAbrirDetalhesModal(curso)}
                                title="Ver detalhes"
                              >
                                Detalhes
                              </button>
                            </td>
                          </tr>
                        );
                      })
                    ) : (
                      <tr>
                        <td colSpan="8" className="text-center py-4">
                          {inscricoes.length > 0 ? (
                            <div className="text-muted">
                              Nenhum curso ativo. Você tem {inscricoes.length}{" "}
                              inscrição(ões) pendente(s)
                            </div>
                          ) : (
                            <div className="text-muted">
                              Nenhum curso encontrado
                            </div>
                          )}
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>

          {/* Inscrições Pendentes */}
          {inscricoes.some((i) => i.status === "pendente") && (
            <div className="card border-warning">
              <div className="card-header bg-warning bg-opacity-10">
                <h5 className="mb-0">Inscrições Pendentes</h5>
              </div>
              <div className="card-body">
                <div className="table-responsive">
                  <table className="table table-sm">
                    <thead>
                      <tr>
                        <th>Curso</th>
                        <th>Nível</th>
                        <th>Período</th>
                        <th>Data</th>
                        <th>Status</th>
                      </tr>
                    </thead>
                    <tbody>
                      {inscricoes
                        .filter((i) => i.status === "pendente")
                        .map((inscricao) => (
                          <tr key={inscricao.id}>
                            <td>
                              {inscricao.curso?.nome || "Curso não encontrado"}
                            </td>
                            <td>{inscricao.nivel}</td>
                            <td>
                              {inscricao.periodo === "manha"
                                ? "Manhã"
                                : "Tarde"}
                            </td>
                            <td>
                              {new Date(
                                inscricao.createdAt
                              ).toLocaleDateString()}
                            </td>
                            <td>
                              <Badge bg="warning">Pendente</Badge>
                            </td>
                          </tr>
                        ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ListaCurso;
